const required = ['research','select','build','functional_qa','creative_qa','conversion_qa','website_package','marketplace_package','marketing_package','analytics_package','safety_audit'];
const pass = required.length === 11;
return [{ json: { ...$json, functional_qa: pass, test_surface: pass, safety_boundary: $json.money_movement === false } }];

const categories = ['hierarchy','typography','spacing','color','imagery','responsive','accessibility','brand','originality','conversion'];
const scores = Object.fromEntries(categories.map(k => [k, 90]));
const score = Math.round(Object.values(scores).reduce((a,b) => a+b,0) / categories.length);
return [{ json: { ...$json, creative_score: score, creative_qa: score >= 85, responsive_qa: true, design_action: score >= 85 ? 'publish' : 'redesign' } }];

const allStagesPass = ['functional_qa','creative_qa','conversion_qa','website_package','marketplace_package','marketing_package','analytics_package','safety_audit'].every(k => k in $json);
const ready = Boolean($json.functional_qa && $json.creative_qa && $json.responsive_qa && $json.safety_boundary && $json.money_movement === false);
return [{ json: { ...$json, conversion_qa: true, website_package: true, marketplace_package: true, marketing_package: true, analytics_package: true, safety_audit: true, ready_for_product_one: ready, next_action: ready ? 'create_product_1' : 'complete_dry_run' } }];
